insert into public.exercises (name, canonical_name, description, equipment, movement_pattern, unilateral_or_bilateral, source_catalog_id, source_group, source_category, source_repository, source_path) values
  ('Neck Flexion Machine', 'neck_flexion_machine__catalog_401', 'Seated in a multi-direction neck machine, facing the pad with the forehead on it and the torso upright and still. Bring the chin toward the chest against the stack, then return to neutral.', 'Machine', 'Neck flexion', 'bilateral', 401, 'Neck — Expansion v1', 'Neck', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Neck Extension Machine', 'neck_extension_machine__catalog_402', 'Seated in a multi-direction neck machine with the back of the head on the pad and the torso upright. Extend the head back from slight flexion to neutral against the stack.', 'Machine', 'Neck extension', 'bilateral', 402, 'Neck — Expansion v1', 'Neck', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Neck Lateral Flexion Machine', 'neck_lateral_flexion_machine__catalog_403', 'Seated side-on in a multi-direction neck machine with the side of the head on the pad. Tilt the ear toward the shoulder against the stack, then switch sides. A set is one side; log the side.', 'Machine', 'Neck lateral flexion', 'unilateral', 403, 'Neck — Expansion v1', 'Neck', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Harness Neck Extension', 'harness_neck_extension__catalog_404', 'Seated at the end of a bench, torso leaning forward with hands on the knees, plates hanging from a head harness. Lift the head from flexion back to neutral and lower under control.', 'Neck harness', 'Neck extension', 'bilateral', 404, 'Neck — Expansion v1', 'Neck', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Band-Resisted Neck Flexion', 'band_resisted_neck_flexion__catalog_405', 'A band anchored behind you at head height and looped over the forehead. Step forward until it is taut, then bring the chin toward the chest and return.', 'Band', 'Neck flexion', 'bilateral', 405, 'Neck — Expansion v1', 'Neck', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Band-Resisted Neck Extension', 'band_resisted_neck_extension__catalog_406', 'A band anchored in front at head height and looped behind the head. Step back until it is taut, then take the head back to neutral and return.', 'Band', 'Neck extension', 'bilateral', 406, 'Neck — Expansion v1', 'Neck', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Isometric Neck Lateral Flexion', 'isometric_neck_lateral_flexion__catalog_407', 'Head upright and still. Place one hand on the same side of the head and press the head into it, building tension slowly, without the head moving. Hold, release slowly, then the other side.', 'Bodyweight', 'Neck lateral flexion', 'unilateral', 407, 'Neck — Expansion v1', 'Neck', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Isometric Neck Rotation', 'isometric_neck_rotation__catalog_408', 'Head upright and still. Place a hand on the side of the forehead and try to turn the head into it without it moving. Hold, release slowly, then the other direction.', 'Bodyweight', 'Neck rotation', 'unilateral', 408, 'Neck — Expansion v1', 'Neck', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Dumbbell Forearm Pronation', 'dumbbell_forearm_pronation__catalog_409', 'Seated with the forearm supported on a bench or thigh, elbow bent to about a right angle and the wrist past the edge. Hold one end of a dumbbell so the other end is the lever, and turn the palm down from palm-up or neutral.', 'Dumbbells', 'Forearm pronation', 'unilateral', 409, 'Forearm & Grip — Expansion v1', 'Arms & grip', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Dumbbell Forearm Supination', 'dumbbell_forearm_supination__catalog_410', 'Same support as pronation: forearm on a bench or thigh, elbow at about a right angle, holding one end of a dumbbell. Turn the palm up from palm-down or neutral.', 'Dumbbells', 'Forearm supination', 'unilateral', 410, 'Forearm & Grip — Expansion v1', 'Arms & grip', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Dumbbell Wrist Radial Deviation', 'dumbbell_wrist_radial_deviation__catalog_411', 'Standing, arm straight at the side, holding one end of a dumbbell with the loaded end in front. Tip the loaded end up by bending the wrist toward the thumb side, then lower.', 'Dumbbells', 'Wrist radial deviation', 'unilateral', 411, 'Forearm & Grip — Expansion v1', 'Arms & grip', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Dumbbell Wrist Ulnar Deviation', 'dumbbell_wrist_ulnar_deviation__catalog_412', 'Standing, arm straight at the side, holding one end of a dumbbell with the loaded end behind. Tip the loaded end up behind you by bending the wrist toward the little-finger side, then lower.', 'Dumbbells', 'Wrist ulnar deviation', 'unilateral', 412, 'Forearm & Grip — Expansion v1', 'Arms & grip', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Cable Wrist Flexion', 'cable_wrist_flexion__catalog_413', 'Seated facing a low pulley with a straight bar, palms up, forearms resting on the thighs and the wrists just past the knees. Curl the wrists up, then lower under control.', 'Cable', 'Wrist flexion', 'bilateral', 413, 'Forearm & Grip — Expansion v1', 'Arms & grip', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Behind-the-Back Barbell Wrist Curl', 'behind_the_back_barbell_wrist_curl__catalog_414', 'Standing, holding a barbell behind the hips at arm''s length with the palms facing back. Curl the wrists up toward the ceiling, then lower; only the wrists move.', 'Barbell', 'Wrist flexion', 'bilateral', 414, 'Forearm & Grip — Expansion v1', 'Arms & grip', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Barbell Finger Curl', 'barbell_finger_curl__catalog_415', 'Seated, forearms on the thighs, holding a barbell palms up. Open the fingers so the bar rolls down to the last finger joints, then close the hand fully to roll it back up; the wrist stays where it is.', 'Barbell', 'Finger flexion', 'bilateral', 415, 'Forearm & Grip — Expansion v1', 'Arms & grip', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Hand Gripper Close', 'hand_gripper_close__catalog_416', 'A torsion-spring hand gripper in one hand. A rep counts when the handles touch; open fully between reps.', 'Hand gripper', 'Grip crush', 'unilateral', 416, 'Forearm & Grip — Expansion v1', 'Arms & grip', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Rubber-Band Finger Extension', 'rubber_band_finger_extension__catalog_417', 'A rubber band around the fingertips and thumb. Open the hand fully against the band, then close slowly.', 'Band', 'Finger extension', 'unilateral', 417, 'Forearm & Grip — Expansion v1', 'Arms & grip', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Hub Grip Lift', 'hub_grip_lift__catalog_418', 'A plate hub on a loading pin. Pinch the hub''s rim with the fingertips and thumb of one hand, lift it to standing and hold. A lift counts when it leaves the floor and is held for the stated time.', 'Grip hub', 'Grip isometric', 'unilateral', 418, 'Forearm & Grip — Expansion v1', 'Arms & grip', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Seated Dip Machine', 'seated_dip_machine__catalog_419', 'Seated in a selectorized dip machine, elbows in at the sides and bent to about a right angle. Press the handles down to just short of lockout, then return.', 'Machine', 'Dip', 'bilateral', 419, 'Machines — Expansion v1', 'Arms & push', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Assisted Dip Machine', 'assisted_dip_machine__catalog_420', 'Kneeling or standing on the counterweight platform, hands on the dip handles. Lower until the upper arms are about level with the floor and press back up; the stack takes part of your body weight.', 'Machine', 'Dip', 'bilateral', 420, 'Machines — Expansion v1', 'Chest & push', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Assisted Pull-Up Machine', 'assisted_pull_up_machine__catalog_421', 'Kneeling on the counterweight pad, hands on the pull-up handles. Pull until the chin clears the handles and lower fully; the stack takes part of your body weight.', 'Machine', 'Vertical pull', 'bilateral', 421, 'Machines — Expansion v1', 'Back & pull', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Belt Squat Machine', 'belt_squat_machine__catalog_422', 'A belt-squat machine: the belt at the hips is attached to the machine''s lever or stack, and the athlete squats on its platform holding the handles. No load rests on the spine.', 'Machine', 'Squat / knee dominant', 'bilateral', 422, 'Machines — Expansion v1', 'Knee dominant', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Horizontal Seated Leg Press', 'horizontal_seated_leg_press__catalog_423', 'A selectorized seated leg press with the platform in front and the push horizontal. Feet on the platform, press out to just short of locking the knees and return.', 'Machine', 'Squat / knee dominant', 'bilateral', 423, 'Machines — Expansion v1', 'Knee dominant', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Smith Machine Bulgarian Split Squat', 'smith_machine_bulgarian_split_squat__catalog_424', 'Smith bar across the upper back, front foot under the bar and the rear foot''s laces on a bench behind. Lower straight down and stand back up; finish one leg, then the other.', 'Machine', 'Unilateral knee dominant', 'unilateral', 424, 'Machines — Expansion v1', 'Knee dominant', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Smith Machine Romanian Deadlift', 'smith_machine_romanian_deadlift__catalog_425', 'Holding the Smith bar at arm''s length, knees soft. Push the hips back and lower the bar down the thighs until the hamstrings limit the hinge, then stand tall.', 'Machine', 'Hip hinge', 'bilateral', 425, 'Machines — Expansion v1', 'Posterior chain', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Smith Machine Reverse Lunge', 'smith_machine_reverse_lunge__catalog_426', 'Smith bar across the upper back. Step one foot back into a lunge, lower until the back knee nears the floor, and drive back to standing. One leg per set, or alternate and count reps per leg.', 'Machine', 'Unilateral knee dominant', 'unilateral', 426, 'Machines — Expansion v1', 'Knee dominant', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Unilateral Machine Lateral Raise', 'unilateral_machine_lateral_raise__catalog_427', 'A lateral-raise machine used one arm at a time: pad on the outside of the upper arm, raise to about shoulder height and lower. Finish one arm, then the other.', 'Machine', 'Shoulder abduction', 'unilateral', 427, 'Machines — Expansion v1', 'Shoulders', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Seated Back Extension Machine', 'seated_back_extension_machine__catalog_428', 'Seated in a selectorized back-extension machine with the pad across the upper back and the thighs and pelvis held by its restraints. Extend the trunk back against the pad, then return. How firmly the pelvis is held decides how much of the work is lumbar extension rather than hip extension.', 'Machine', 'Trunk extension', 'bilateral', 428, 'Machines — Expansion v1', 'Posterior chain', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Rotary Torso Machine', 'rotary_torso_machine__catalog_429', 'Seated in a rotary torso machine with the hips and legs fixed and the chest against the pads. Rotate the trunk against the stack to one side and return; set the machine for the other side.', 'Machine', 'Rotation', 'unilateral', 429, 'Machines — Expansion v1', 'Core', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Hip Thrust Machine', 'hip_thrust_machine__catalog_430', 'A hip-thrust machine: back on the pad, the belt or roller across the hips, feet on the platform. Drive the hips up to full extension and lower.', 'Machine', 'Hip extension', 'bilateral', 430, 'Machines — Expansion v1', 'Hips & glutes', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Zercher Deadlift', 'zercher_deadlift__catalog_431', 'The bar starts on the floor (or low blocks). Squat down, hook the bar into the crooks of the elbows with the hands together, brace, and stand up with it; lower it back to the floor each rep.', 'Barbell', 'Hip hinge', 'bilateral', 431, 'Barbell & Lower Body — Expansion v1', 'Posterior chain', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Trap-Bar Deadlift', 'trap_bar_deadlift__catalog_432', 'Standing inside a hexagonal (trap) bar, hands on the side handles. Lift from the floor to standing. Note whether you used the high or the low handles: they are different starting heights.', 'Trap bar', 'Hip hinge', 'bilateral', 432, 'Barbell & Lower Body — Expansion v1', 'Posterior chain', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Sumo Deadlift', 'sumo_deadlift__catalog_433', 'Feet set wide, toes out, the bar over mid-foot and the hands inside the knees. Push the floor apart and stand up with the bar; lower it to the floor each rep.', 'Barbell', 'Hip hinge', 'bilateral', 433, 'Barbell & Lower Body — Expansion v1', 'Posterior chain', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Safety-Bar Squat', 'safety_bar_squat__catalog_434', 'A cambered safety squat bar on the upper back with its handles held in front. Squat to depth and stand up.', 'Safety squat bar', 'Squat / knee dominant', 'bilateral', 434, 'Barbell & Lower Body — Expansion v1', 'Knee dominant', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Loading-Pin Belt Squat', 'loading_pin_belt_squat__catalog_435', 'A dip or belt-squat belt with a chain to a loading pin of plates hanging between two raised platforms. Squat between the platforms and stand up.', 'Loading pin', 'Squat / knee dominant', 'bilateral', 435, 'Barbell & Lower Body — Expansion v1', 'Knee dominant', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Reverse Nordic Curl', 'reverse_nordic_curl__catalog_436', 'Kneeling upright with the hips straight. Lean the whole body back as one piece by letting the knees bend, as far as you can control, then return by straightening the knees.', 'Bodyweight', 'Knee extension', 'bilateral', 436, 'Barbell & Lower Body — Expansion v1', 'Knee dominant', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Dumbbell Lateral Lunge', 'dumbbell_lateral_lunge__catalog_437', 'A dumbbell in each hand. Step wide to one side, sit back onto that leg with the other straight, then push back to the start. Finish one side or alternate; count reps per side.', 'Dumbbells', 'Lateral lunge', 'unilateral', 437, 'Barbell & Lower Body — Expansion v1', 'Knee dominant', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
  ('Single-Leg Seated Leg Curl', 'single_leg_seated_leg_curl__catalog_438', 'Seated leg-curl machine, thigh pad down, one leg at a time. Curl the heel under the seat and return to near straight.', 'Machine', 'Knee flexion', 'unilateral', 438, 'Barbell & Lower Body — Expansion v1', 'Posterior chain', 'LocalForgeWeb/Sports-genome', 'client/src/lib/exerciseCatalogAdditions.ts'),
